import{_ as n,l as o,o as e,c as l,v as r,p as d,x as i,d as E,i as s,S as u}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Kudo Unigram 论文","description":"","frontmatter":{"title":"Kudo Unigram 论文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kudo-unigram.md","filePath":"llm/kudo-unigram.md","lastUpdated":1789023840000}'),m={name:"llm/kudo-unigram.md"};function p(h,a,c,g,B,A){const t=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="kudo-unigram-论文" tabindex="-1">Kudo Unigram 论文 <a class="header-anchor" href="#kudo-unigram-论文" aria-label="Permalink to &quot;Kudo Unigram 论文&quot;">​</a></h1><div class="epigraph"><p>与其死守一条贪心切分，不如用一个 unigram 语言模型给同一句多种子词切分，训练时采样，解码时取可能切分。</p><footer>—— Kudo, Subword Regularization: Improving Neural Network Translation Models with Multiple Subword Candidates, ACL 2018</footer></div><p><a href="/llm/sennrich-bpe">Sennrich BPE</a> 把切分固定成一条贪心路径。Kudo 2018 的缺口是：<strong>这一条路径被模型当成真理，分词噪声与领域偏移都会伤</strong>。他提出子词正则：用 unigram LM 在子词序列上定义 \\(p(x)\\)，训练时从多种切分中采样。SentencePiece 的 unigram 模式实现了这条。本篇对照论文，不把 SentencePiece 工程手册重写一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BPE 编码确定性：同一词总是同一碎片。若训练语料的空格、噪声与测试不同，碎片错位，嵌入从未对齐。字符级过稳但序列长。Kudo 要在训练引入切分的随机性，使模型对「哪一种合法切分」鲁棒，推理仍可用最可能切分或 n-best。</p><p>Unigram 假设子词独立，句子概率是碎片概率之积。词表用 EM 一类迭代从种子碎片里剪到目标大小。这与 BPE 的合并方向相反：从大候选集删除，而不是从小到大合并。</p><h3 id="正则化的是输入符号-不是权重衰减" tabindex="-1">正则化的是输入符号，不是权重衰减 <a class="header-anchor" href="#正则化的是输入符号-不是权重衰减" aria-label="Permalink to &quot;正则化的是输入符号，不是权重衰减&quot;">​</a></h3><p>采样切分等于对输入做数据增强。论文把它写成翻译训练的一部分，BLEU 提升来自鲁棒性。它不是语言模型的 dropout 理论证明，是 NMT 实验。<span class="marginnote">Unigram 词表与 BPE 词表即使 \\(|V|\\) 相同，碎片集合也不同，不可把一篇的 BLEU 差解释成「算法永远更优」。对照必须锁语料与预处理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="种子、em、采样与-viterbi" tabindex="-1">种子、EM、采样与 Viterbi <a class="header-anchor" href="#种子、em、采样与-viterbi" aria-label="Permalink to &quot;种子、EM、采样与 Viterbi&quot;">​</a></h3><p>建一个较大的种子子词集（高频子串），用 unigram LM 的 EM 估计每个碎片概率，删掉对似然贡献小的，直到 \\(|V|\\)。编码：在格子上做 Viterbi 得最优切分，或按概率采样。训练 NMT 时对每个句采样一切分；测试用 Viterbi。</p>',11)),(e(),d(u,null,{default:i(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E7%A7%8D%E5%AD%90%E5%AD%90%E8%AF%8D%E9%9B%86%22%5D%20--%3E%20EM%5B%22Unigram%20EM%20%E4%BC%B0%E6%A6%82%E7%8E%87%22%5D%0A%20%20EM%20--%3E%20PRUNE%5B%22%E5%88%A0%E9%99%A4%E4%BD%8E%E8%B4%A1%E7%8C%AE%E7%A2%8E%E7%89%87%22%5D%0A%20%20PRUNE%20--%3E%20V%5B%22%E7%9B%AE%E6%A0%87%E8%AF%8D%E8%A1%A8%22%5D%0A%20%20V%20--%3E%20SAMP%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E9%87%87%E6%A0%B7%E5%88%87%E5%88%86%22%5D%0A%20%20V%20--%3E%20VIT%5B%22%E6%B5%8B%E8%AF%95%EF%BC%9AViterbi%20%E5%88%87%E5%88%86%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多种切分让同一词干的不同碎片边界都见过梯度，形态变化不那么依赖「碰巧与训练合并一致」。测试若仍 Viterbi，则与训练分布有差——这是正则的典型代价，论文用实验表明净效果为正。若测试也采样，翻译解码会引入额外随机，一般不用。</p><p>相对 BPE，unigram 对罕见专名的切分更「碎」还是更「整」取决于种子与删除过程，没有单方向。工程上后来 SentencePiece 同时提供 BPE 与 unigram 后端，选择是超参。</p><p><span class="marginnote">Subword dropout（后来 BPE dropout）用另一机制打乱 BPE 切分。Kudo 原文的主路径是 unigram 采样。引用「子词正则」时要说清采样来自哪一个模型。</span></p><h3 id="对-llm-词表的遗产" tabindex="-1">对 LLM 词表的遗产 <a class="header-anchor" href="#对-llm-词表的遗产" aria-label="Permalink to &quot;对 LLM 词表的遗产&quot;">​</a></h3><p>当代大模型更多用字节级 BPE，而不是训练期切分采样。论文的遗产是：<strong>切分是模型的一部分，可以随机化</strong>。数据受限、形态丰富语言仍可能从正则里获益。不要用 2018 的 NMT BLEU 证明某 LLM 必须改 unigram。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Unigram 独立假设很强，碎片之间的合并偏好（BPE 显式编码了历史合并）丢失。实现比 BPE 重（EM、格子）。解码器若与训练不同（另一个 SentencePiece 模型），采样分布作废。多语言大词表上 EM 贵，工业上常退回 BPE。</p><p>论文评测仍是翻译。没有报告十亿参数 LM 的 perplexity。附录对照到此为止：问题（单一切分过拟合）→ 方法（unigram + 采样）→ 当代默认并未全盘采用。</p><p><span class="marginnote">题名 <em>Subword Regularization: Improving Neural Network Translation Models with Multiple Subword Candidates</em>。作者 Taku Kudo。ACL 2018。SentencePiece 是同一作者线的工具，论文与工具不要混成一篇实验。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kudo 2018 用 unigram LM 定义多种合法切分，训练采样当正则。</li><li>词表由 EM 删除而非 BPE 合并得到。</li><li>测试常用 Viterbi，与训练分布有意不一致。</li><li>遗产是「切分可随机化」；现代 LLM 默认仍多为 BPE。</li><li>出处：Kudo, ACL 2018。</li></ul>',12))])}const _=n(m,[["render",p]]);export{b as __pageData,_ as default};
